sys_script_include.script:
var FilterAssetsByCompany = Class.create();
FilterAssetsByCompany.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    filter: function(companySysId) {
        if (!companySysId) {
            return ''; // Wenn kein Wert vorhanden ist, wird ein leerer Filter zurückgegeben
        }

        var gr = new GlideRecord('alm_asset');
        gr.addQuery('company', companySysId); // Filtere nach der übergebenen Firma
       // gr.orderBy('sys_created_on'); // Sortiere nach Erstellungsdatum (älteste zuerst)
        gr.query();

        var sysIdList = [];
        while (gr.next()) {
            sysIdList.push(gr.getValue('sys_id')); // Füge jeden Eintrag in die Liste ein
        }

        // Rückgabe des Filters im passenden Format ("sys_idIN...")
       // return 'sys_idIN' + sysIdList.join(',')
	   return sysIdList.join(',');
    },
    type: 'FilterAssetsByCompany'
});
